// Extraire et valider les paramètres (API v2)
const input = $input.first().json;
const query = input.query || {};

const traite = query.traite || null;
const page = query.page || null;
const includeTranslations = query.include_translations === "true" || query.include_translations === true;
const targetLanguage = query.target_language || "fr";
const corpus = query.corpus || null;  // API v2: corpus parameter for disambiguation

// Validation
const errors = [];
if (!traite) errors.push('Le paramètre "traite" est requis');
if (!page) errors.push('Le paramètre "page" est requis');

if (errors.length > 0) {
  return [{
    json: {
      valid: false,
      error: {
        code: 400,
        message: errors.join(', '),
        status: 'BAD_REQUEST'
      }
    }
  }];
}

return [{
  json: {
    valid: true,
    traite: traite,
    page: page,
    includeTranslations: includeTranslations,
    targetLanguage: targetLanguage,
    corpus: corpus  // API v2: pass corpus for disambiguation
  }
}];

// Formater la réponse de l'API (API v2)
const input = $input.first().json;

const data = input.body || input;
const statusCode = input.statusCode || 200;

// API v2: Handle AmbiguousReferenceError (400 with error_type)
if (statusCode === 400 && data.error_type === 'AmbiguousReferenceError') {
  return [{
    json: {
      success: false,
      error: {
        code: 400,
        message: data.message || 'Référence ambiguë - veuillez spécifier le corpus',
        status: 'AMBIGUOUS_REFERENCE',
        error_type: 'AmbiguousReferenceError',
        options: data.options || []  // Available corpus options
      }
    }
  }];
}

// Erreur API
if (statusCode >= 400) {
  return [{
    json: {
      success: false,
      error: {
        code: statusCode,
        message: data.error?.message || data.message || 'Page non trouvée',
        status: 'PAGE_NOT_FOUND'
      }
    }
  }];
}

// Retourner la réponse avec success flag
return [{
  json: {
    success: true,
    ...data
  }
}];

